B.adL=new A.a9(B.cj,["q1","Nh\u1eadn bi\u1ebft",1.5,"X\xe1c \u0111\u1ecbnh th\u1ec3 th\u01a1 v\xe0 nh\xe2n v\u1eadt tr\u1eef t\xecnh trong v\u0103n b\u1ea3n tr\xean.",'Th\u1ec3 th\u01a1 t\u1ef1 do (ho\u1eb7c ch\u1ee7 y\u1ebfu 7\u20138 ch\u1eef \u0111an xen t\u1ef1 do); nh\xe2n v\u1eadt tr\u1eef t\xecnh l\xe0 ng\u01b0\u1eddi con/ch\xe1u x\u01b0ng "con".','N\xeau \u0111\xfang th\u1ec3 th\u01a1 (0.75\u0111) v\xe0 ch\u1ec9 \u0111\xfang nh\xe2n v\u1eadt tr\u1eef t\xecnh "con" (0.75\u0111).'],t.EU)
B.adJ=new A.a9(B.cj,["q2","Th\xf4ng hi\u1ec3u",1.5,"Ch\u1ec9 ra hai h\xecnh \u1ea3nh g\u1eafn v\u1edbi s\u1ef1 t\u1ea3o t\u1ea7n, hy sinh c\u1ee7a ng\u01b0\u1eddi b\xe0 trong kh\u1ed5 th\u01a1 th\u1ee9 hai.",'"B\xe1t c\u01a1m \u0111\u1ea7y gi\u1ea5u n\u1eeda ph\u1ea7n khoai", "ng\u1ecdn \u0111\xe8n d\u1ea7u chong su\u1ed1t \u0111\xeam th\xe1ng ch\u1ea1p", "\xe1o b\xe0 v\xe1 ch\u1eb1ng t\u1eebng m\u0169i ch\u1ec9 d\xe0i".',"Tr\xedch \u0111\xfang 2 h\xecnh \u1ea3nh (1.0\u0111) v\xe0 gi\u1ea3i th\xedch ng\u1eafn g\u1ecdn \xfd ngh\u0129a (0.5\u0111)."],t.EU)
B.adH=new A.a9(B.cj,["q3","Th\xf4ng hi\u1ec3u",2,'Ph\xe2n t\xedch hi\u1ec7u qu\u1ea3 ngh\u1ec7 thu\u1eadt c\u1ee7a s\u1ef1 \u0111\u1ed1i l\u1eadp kh\xf4ng gian gi\u1eefa "ph\u1ed1 th\u1ecb s\xe1ng \xe1nh \u0111\xe8n cao \xe1p" v\xe0 "gi\xe0n hoa t\xedm ng\xe1t s\xe2n sau" \u1edf kh\u1ed5 cu\u1ed1i.',"Kh\u1eafc h\u1ecda s\u1ef1 \u0111\u1ed1i l\u1eadp gi\u1eefa nh\u1ecbp s\u1ed1ng hi\u1ec7n \u0111\u1ea1i h\u1ed1i h\u1ea3 v\u1edbi k\xfd \u1ee9c b\xecnh y\xean n\u01a1i qu\xea nh\xe0, l\xe0m n\u1ed5i b\u1eadt n\u1ed7i nh\u1edb v\xe0 \u0111i\u1ec3m t\u1ef1a tinh th\u1ea7n b\u1ec1n b\u1ec9 trong t\xe2m h\u1ed3n ng\u01b0\u1eddi con.","N\xeau \u0111\u01b0\u1ee3c hai v\u1ebf \u0111\u1ed1i l\u1eadp (0.75\u0111) v\xe0 hi\u1ec7u qu\u1ea3 bi\u1ec3u \u0111\u1ea1t c\u1ea3m x\xfac (1.25\u0111)."],t.EU)
B.adE=new A.a9(B.cj,["q4","V\u1eadn d\u1ee5ng",2,"Th\xf4ng \u0111i\u1ec7p n\xe0o trong b\xe0i th\u01a1 c\xf3 \xfd ngh\u0129a s\xe2u s\u1eafc nh\u1ea5t \u0111\u1ed1i v\u1edbi anh/ch\u1ecb? V\xec sao?","Th\xf4ng \u0111i\u1ec7p bi\u1ebft tr\xe2n tr\u1ecdng c\u1ed9i ngu\u1ed3n, gia \u0111\xecnh v\xe0 gi\u1eef nh\u1eefng kho\u1ea3ng l\u1eb7ng t\xe2m h\u1ed3n gi\u1eefa nh\u1ecbp s\u1ed1ng v\u1ed9i v\xe3.","N\xeau r\xf5 1 th\xf4ng \u0111i\u1ec7p ph\xf9 h\u1ee3p (0.75\u0111), l\xfd gi\u1ea3i thuy\u1ebft ph\u1ee5c, ch\xe2n th\xe0nh (1.25\u0111)."],t.EU)
B.adO=new A.a9(B.cj,["q5","Vi\u1ebft \u0111o\u1ea1n v\u0103n (~150 ch\u1eef)",3,"Vi\u1ebft m\u1ed9t \u0111o\u1ea1n v\u0103n ng\u1eafn (kho\u1ea3ng 150 ch\u1eef) tr\xecnh b\xe0y suy ngh\u0129 v\u1ec1 vai tr\xf2 c\u1ee7a k\xfd \u1ee9c gia \u0111\xecnh \u0111\u1ed1i v\u1edbi m\u1ed7i ng\u01b0\u1eddi tr\u1ebb h\xf4m nay.","K\xfd \u1ee9c gia \u0111\xecnh l\xe0 \u0111i\u1ec3m t\u1ef1a tinh th\u1ea7n gi\xfap ng\u01b0\u1eddi tr\u1ebb v\u1eefng v\xe0ng tr\u01b0\u1edbc \xe1p l\u1ef1c, nu\xf4i d\u01b0\u1ee1ng l\xf2ng nh\xe2n \xe1i v\xe0 \xfd th\u1ee9c tr\xe1ch nhi\u1ec7m v\u1edbi ng\u01b0\u1eddi th\xe2n.","\u0110\xfang h\xecnh th\u1ee9c \u0111o\u1ea1n v\u0103n (0.5\u0111); lu\u1eadn \u0111i\u1ec3m r\xf5, ph\xe2n t\xedch s\xe2u (1.5\u0111); d\u1eabn ch\u1ee9ng v\xe0 di\u1ec5n \u0111\u1ea1t t\u1ef1 nhi\xean (1.0\u0111)."],t.EU)
B.a0F=s([B.adL,B.adJ,B.adH,B.adE,B.adO],t.Mq)
B.adB=new A.a9(B.pJ,["sample-12-poem","Kho\u1ea3ng l\u1eb7ng b\xean gi\xe0n hoa gi\u1ea5y",12,"Th\u01a1 hi\u1ec7n \u0111\u1ea1i","Ng\u1eef li\u1ec7u luy\u1ec7n t\u1eadp V\u0103nM\u1ea1ch","Ng\u1eef li\u1ec7u ngo\xe0i SGK theo \u0111\u1ecbnh h\u01b0\u1edbng GDPT 2018 (L\u1edbp 12)","Chi\u1ec1u nghi\xeang tr\xean m\xe1i ng\xf3i th\xe2m n\xe2u\nGi\xe0n hoa gi\u1ea5y r\u1ee5ng v\xe0i c\xe1nh m\u1ecfng\nB\xe0 ng\u1ed3i ch\u1ea3i l\u1ea1i m\xe1i \u0111\u1ea7u s\u01b0\u01a1ng tr\u1eafng\nNghe ti\u1ebfng chu\xf4ng ch\xf9a ng\xe2n qua r\u1eb7ng cau.\n\nCon l\u1edbn l\xean t\u1eeb nh\u1eefng m\xf9a gi\xf3 b\u1ea5c\nB\xe1t c\u01a1m \u0111\u1ea7y gi\u1ea5u n\u1eeda ph\u1ea7n khoai\nNg\u1ecdn \u0111\xe8n d\u1ea7u chong su\u1ed1t \u0111\xeam th\xe1ng ch\u1ea1p\n\xc1o b\xe0 v\xe1 ch\u1eb1ng t\u1eebng m\u0169i ch\u1ec9 d\xe0i.\n\nNay ph\u1ed1 th\u1ecb s\xe1ng \xe1nh \u0111\xe8n cao \xe1p\nChuy\u1ebfn xe \u0111\xeam h\u1ed1i h\u1ea3 qua c\u1ea7u\nCh\u1ec9 c\u1ea7n nh\u1eafm m\u1eaft nghe l\xf2ng l\u1eafng l\u1ea1i\nV\u1eabn th\u1ea5y gi\xe0n hoa t\xedm ng\xe1t s\xe2n sau.",B.a0F],t.yf)
B.adG=new A.a9(B.cj,["q1","Nh\u1eadn bi\u1ebft",1.5,"X\xe1c \u0111\u1ecbnh ng\xf4i k\u1ec3 v\xe0 kh\xf4ng gian ch\xednh c\u1ee7a \u0111o\u1ea1n tr\xedch.","Ng\xf4i k\u1ec3 th\u1ee9 ba; kh\xf4ng gian ch\xednh l\xe0 m\u1ed9t nh\xe0 ga nh\u1ecf khu\u1ea5t sau \u0111\u1ed3i th\xf4ng v\xe0o chi\u1ec1u v\xe0 \u0111\xeam cu\u1ed1i n\u0103m.","\u0110\xfang ng\xf4i th\u1ee9 ba (0.75\u0111) v\xe0 kh\xf4ng gian nh\xe0 ga (0.75\u0111)."],t.EU)
B.adR=new A.a9(B.cj,["q2","Th\xf4ng hi\u1ec3u",1.5,"V\xec sao \xf4ng L\xe2m mu\u1ed1n gi\u1eef l\u1ea1i chi\u1ebfc \u0111\u1ed3ng h\u1ed3 qu\u1ea3 l\u1eafc thay v\xec d\xf9ng b\u1ea3ng \u0111i\u1ec7n t\u1eed?","V\xec \xf4ng tin m\u1eb7t \u0111\u1ed3ng h\u1ed3 quen thu\u1ed9c v\xe0 ti\u1ebfng t\xedch t\u1eafc \u0111\u1ec1u gi\xfap h\xe0nh kh\xe1ch \u0111i t\xe0u \u0111\xeam c\u1ea3m th\u1ea5y y\xean t\xe2m, \u1ea5m \xe1p h\u01a1n.","N\xeau \u0111\xfang l\xfd do t\u1eeb l\u1eddi n\xf3i v\xe0 suy ngh\u0129 c\u1ee7a nh\xe2n v\u1eadt (1.5\u0111)."],t.EU)
B.adQ=new A.a9(B.cj,["q3","Th\xf4ng hi\u1ec3u",2,"H\xe0nh \u0111\u1ed9ng pha \u1ea5m tr\xe0 g\u1eebng n\xf3ng v\xe0 lau m\u1eb7t k\xednh \u0111\u1ed3ng h\u1ed3 l\xfac t\xe0u tr\u1ec5 th\u1ec3 hi\u1ec7n v\u1ebb \u0111\u1eb9p g\xec \u1edf nh\xe2n v\u1eadt \xf4ng L\xe2m?","Th\u1ec3 hi\u1ec7n s\u1ef1 t\u1eadn t\u1ee5y v\u1edbi c\xf4ng vi\u1ec7c b\xecnh d\u1ecb v\xe0 t\u1ea5m l\xf2ng chu \u0111\xe1o, \u1ea5m \xe1p, lu\xf4n quan t\xe2m \u0111\u1ebfn nh\u1eefng ng\u01b0\u1eddi lao \u0111\u1ed9ng xung quanh.","Ch\u1ec9 ra \u0111\u01b0\u1ee3c c\u1ea3 ph\u1ea9m ch\u1ea5t tr\xe1ch nhi\u1ec7m v\u1edbi ngh\u1ec1 v\xe0 t\xecnh ng\u01b0\u1eddi \u1ea5m \xe1p (2.0\u0111)."],t.EU)
B.adM=new A.a9(B.cj,["q4","V\u1eadn d\u1ee5ng",2,"Chi ti\u1ebft \xe1nh s\xe1ng v\xe0ng \u1ea5m \u1edf cu\u1ed1i truy\u1ec7n g\u1ee3i cho anh/ch\u1ecb suy ngh\u0129 g\xec v\u1ec1 gi\xe1 tr\u1ecb c\u1ee7a nh\u1eefng \u0111i\u1ec1u b\xecnh d\u1ecb trong cu\u1ed9c s\u1ed1ng?","Nh\u1eefng \u0111i\u1ec1u gi\u1ea3n d\u1ecb, \xe2m th\u1ea7m nh\u01b0ng xu\u1ea5t ph\xe1t t\u1eeb t\xecnh y\xeau th\u01b0\u01a1ng v\xe0 tr\xe1ch nhi\u1ec7m lu\xf4n mang l\u1ea1i s\u1ef1 \u1ea5m \xe1p v\xe0 ni\u1ec1m tin cho con ng\u01b0\u1eddi.","Gi\u1ea3i th\xedch s\xe2u s\u1eafc \xfd ngh\u0129a bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a chi ti\u1ebft k\u1ebft (2.0\u0111)."],t.EU)
B.adN=new A.a9(B.cj,["q5","Vi\u1ebft \u0111o\u1ea1n v\u0103n (~150 ch\u1eef)",3,"Vi\u1ebft \u0111o\u1ea1n v\u0103n kho\u1ea3ng 150 ch\u1eef c\u1ea3m nh\u1eadn v\u1ebb \u0111\u1eb9p c\u1ee7a nh\xe2n v\u1eadt \xf4ng L\xe2m trong \u0111o\u1ea1n tr\xedch.","\xd4ng L\xe2m hi\u1ec7n l\xean v\u1edbi v\u1ebb \u0111\u1eb9p l\u1eb7ng l\u1ebd c\u1ee7a ng\u01b0\u1eddi lao \u0111\u1ed9ng t\u1eadn t\xe2m, tr\xe2n tr\u1ecdng k\xfd \u1ee9c v\xe0 gi\xe0u t\xecnh th\u01b0\u01a1ng.","\u0110\u1ee7 b\u1ed1 c\u1ee5c \u0111o\u1ea1n v\u0103n (0.5\u0111), b\xe1m s\xe1t chi ti\u1ebft truy\u1ec7n (1.5\u0111), c\u1ea3m nh\u1eadn tinh t\u1ebf, m\u1ea1ch l\u1ea1c (1.0\u0111)."],t.EU)
B.a8R=s([B.adG,B.adR,B.adQ,B.adM,B.adN],t.Mq)
B.adA=new A.a9(B.pJ,["sample-11-prose","Ng\u01b0\u1eddi gi\u1eef nh\u1ecbp \u0111\u1ed3ng h\u1ed3 ga c\u0169",11,"Truy\u1ec7n ng\u1eafn","Ng\u1eef li\u1ec7u luy\u1ec7n t\u1eadp V\u0103nM\u1ea1ch","Ng\u1eef li\u1ec7u ngo\xe0i SGK theo \u0111\u1ecbnh h\u01b0\u1edbng GDPT 2018 (L\u1edbp 11)",'Nh\xe0 ga nh\u1ecf n\u1eb1m khu\u1ea5t sau \u0111\u1ed3i th\xf4ng, m\u1ed7i ng\xe0y ch\u1ec9 c\xf2n hai chuy\u1ebfn t\xe0u \u0111\u1ecba ph\u01b0\u01a1ng d\u1eebng l\u1ea1i v\xe0i ph\xfat r\u1ed3i l\u1eb7ng l\u1ebd tr\xf4i v\xe0o s\u01b0\u01a1ng n\xfai. \xd4ng L\xe2m l\xe0m c\xf4ng vi\u1ec7c g\xe1c ghi v\xe0 l\xean d\xe2y c\xf3t chi\u1ebfc \u0111\u1ed3ng h\u1ed3 qu\u1ea3 l\u1eafc treo gi\u1eefa s\u1ea3nh ch\u1edd \u0111\xe3 g\u1ea7n ba m\u01b0\u01a1i n\u0103m. Nhi\u1ec1u l\u1ea7n tr\u01b0\u1edfng ga tr\u1ebb g\u1ee3i \xfd thay b\u1eb1ng b\u1ea3ng \u0111i\u1ec7n t\u1eed hi\u1ec7n \u0111\u1ea1i cho \u0111\u1ee1 v\u1ea5t v\u1ea3, \xf4ng ch\u1ec9 c\u01b0\u1eddi hi\u1ec1n: "Kh\xe1ch \u0111i t\xe0u \u0111\xeam hay nh\xecn m\u1eb7t s\u1ed1 tr\u1eafng \u0111\u1ec3 \u0111\u1ee1 s\u1ed1t ru\u1ed9t. Nghe ti\u1ebfng t\xedch t\u1eafc \u0111\u1ec1u, ng\u01b0\u1eddi ta bi\u1ebft th\u1eddi gian v\u1eabn \u0111ang \u0111i c\xf9ng m\xecnh." Chi\u1ec1u cu\u1ed1i n\u0103m, chuy\u1ebfn t\xe0u mu\u1ed9n b\u1ecb k\u1eb9t do s\u1ea1t l\u1edf nh\u1eb9 ph\xeda \u0111\xe8o B\u1eafc. C\u1ea3 s\u1ea3nh ga ch\u1ec9 c\xf2n v\xe0i c\xf4ng nh\xe2n v\u1ec1 qu\xea mu\u1ed9n ng\u1ed3i co ro. \xd4ng L\xe2m pha \u1ea5m tr\xe0 g\u1eebng n\xf3ng, \u0111\u1eb7t l\xean chi\u1ebfc b\xe0n g\u1ed7 r\u1ed3i l\u1ea1i b\u1eafc gh\u1ebf lau s\u1ea1ch m\u1eb7t k\xednh \u0111\u1ed3ng h\u1ed3. Khi c\xf2i t\xe0u v\u1ecdng l\u1ea1i t\u1eeb s\u01b0\u1eddn n\xfai l\xfac g\u1ea7n n\u1eeda \u0111\xeam, \xe1nh s\xe1ng v\xe0ng \u1ea5m t\u1eeb \xf4 c\u1eeda ga nh\u1ecf h\u1eaft ra s\xe2n ga nh\u01b0 m\u1ed9t l\u1eddi ch\xe0o b\xecnh d\u1ecb.',B.a8R],t.yf)
B.adP=new A.a9(B.cj,["q1","Nh\u1eadn bi\u1ebft",1.5,"V\u1ea5n \u0111\u1ec1 ngh\u1ecb lu\u1eadn ch\xednh \u0111\u01b0\u1ee3c b\xe0n \u0111\u1ebfn trong v\u0103n b\u1ea3n l\xe0 g\xec?","Vai tr\xf2 v\xe0 \xfd ngh\u0129a c\u1ee7a vi\u1ec7c bi\u1ebft l\u1eafng nghe th\u1ef1c s\u1ef1 trong \u0111\u1eddi s\u1ed1ng hi\u1ec7n \u0111\u1ea1i.","N\xeau \u0111\xfang v\u1ea5n \u0111\u1ec1 l\u1eafng nghe trong b\u1ed1i c\u1ea3nh hi\u1ec7n \u0111\u1ea1i (1.5\u0111)."],t.EU)
B.adK=new A.a9(B.cj,["q2","Nh\u1eadn bi\u1ebft / Th\xf4ng hi\u1ec3u",1.5,'Theo t\xe1c gi\u1ea3, th\u1ebf n\xe0o l\xe0 "l\u1eafng nghe th\u1ef1c s\u1ef1"?',"L\xe0 t\u1ea1m g\xe1c \u0111\u1ecbnh ki\u1ebfn \u0111\u1ec3 \u0111\u1eb7t m\xecnh v\xe0o c\xe2u chuy\u1ec7n, c\u1ea3m x\xfac v\xe0 ho\xe0n c\u1ea3nh c\u1ee7a ng\u01b0\u1eddi \u0111\u1ed1i di\u1ec7n, ch\u1ee9 kh\xf4ng ch\u1ec9 im l\u1eb7ng ch\u1edd \u0111\u1ebfn l\u01b0\u1ee3t n\xf3i.","Tr\xedch/di\u1ec5n gi\u1ea3i \u0111\xfang \xfd trong \u0111o\u1ea1n 2 c\u1ee7a v\u0103n b\u1ea3n (1.5\u0111)."],t.EU)
B.adI=new A.a9(B.cj,["q3","Th\xf4ng hi\u1ec3u",2,"Ph\xe2n t\xedch t\xe1c d\u1ee5ng c\u1ee7a c\xe2u m\u1edf \u0111\u1ea7u trong vi\u1ec7c d\u1eabn d\u1eaft v\u1ea5n \u0111\u1ec1 ngh\u1ecb lu\u1eadn.",'T\u1ea1o s\u1ef1 t\u01b0\u01a1ng ph\u1ea3n gi\u1eefa t\u1ed1c \u0111\u1ed9 "l\xean ti\u1ebfng" d\u1ec5 d\xe0ng v\u1edbi s\u1ef1 khan hi\u1ebfm c\u1ee7a "l\u1eafng nghe", qua \u0111\xf3 n\xeau b\u1eadt t\xednh c\u1ea5p thi\u1ebft c\u1ee7a v\u1ea5n \u0111\u1ec1.',"Ch\u1ec9 ra ph\xe9p \u0111\u1ed1i l\u1eadp v\xe0 hi\u1ec7u qu\u1ea3 thu h\xfat ng\u01b0\u1eddi \u0111\u1ecdc (2.0\u0111)."],t.EU)
B.adF=new A.a9(B.cj,["q4","V\u1eadn d\u1ee5ng",2,'Anh/ch\u1ecb c\xf3 \u0111\u1ed3ng t\xecnh v\u1edbi nh\u1eadn \u0111\u1ecbnh "H\u1ecdc c\xe1ch nghe ch\u1eadm l\u1ea1i c\u0169ng l\xe0 c\xe1ch r\xe8n luy\u1ec7n t\u01b0 duy ph\u1ea3n bi\u1ec7n t\u1ec9nh t\xe1o" kh\xf4ng? Gi\u1ea3i th\xedch ng\u1eafn g\u1ecdn.',"\u0110\u1ed3ng t\xecnh v\xec nghe k\u1ef9 gi\xfap thu th\u1eadp \u0111\u1ee7 th\xf4ng tin, nh\u1eadn ra \u0111i\u1ec3m h\u1ee3p l\xfd ho\u1eb7c l\u1ed7 h\u1ed5ng l\u1eadp lu\u1eadn thay v\xec ph\xe1n x\xe9t c\u1ea3m t\xednh.","Th\u1ec3 hi\u1ec7n quan \u0111i\u1ec3m r\xf5 r\xe0ng v\xe0 l\xfd gi\u1ea3i h\u1ee3p logic (2.0\u0111)."],t.EU)
B.adS=new A.a9(B.cj,["q5","Vi\u1ebft \u0111o\u1ea1n v\u0103n (~150 ch\u1eef)",3,"Vi\u1ebft m\u1ed9t \u0111o\u1ea1n v\u0103n kho\u1ea3ng 150 ch\u1eef b\xe0n v\u1ec1 c\xe1ch r\xe8n luy\u1ec7n th\xf3i quen l\u1eafng nghe t\xedch c\u1ef1c \u1edf l\u1ee9a tu\u1ed5i h\u1ecdc sinh.","C\u1ea7n t\u1eadp trung nh\xecn ng\u01b0\u1eddi n\xf3i, kh\xf4ng ng\u1eaft l\u1eddi, \u0111\u1eb7t c\xe2u h\u1ecfi l\xe0m r\xf5 v\xe0 ki\u1ec3m ch\u1ee9ng th\xf4ng tin tr\u01b0\u1edbc khi ph\u1ea3n h\u1ed3i.","Gi\u1ea3i ph\xe1p c\u1ee5 th\u1ec3, thi\u1ebft th\u1ef1c (1.5\u0111), l\u1eadp lu\u1eadn ch\u1eb7t ch\u1ebd (1.0\u0111), \u0111\xfang dung l\u01b0\u1ee3ng v\xe0 chu\u1ea9n ch\xednh t\u1ea3 (0.5\u0111)."],t.EU)
B.a28=s([B.adP,B.adK,B.adI,B.adF,B.adS],t.Mq)
B.adz=new A.a9(B.pJ,["sample-10-arg","Bi\u1ebft l\u1eafng nghe trong th\u1eddi \u0111\u1ea1i v\u1ed9i v\xe3",10,"Ngh\u1ecb lu\u1eadn x\xe3 h\u1ed9i","Ng\u1eef li\u1ec7u luy\u1ec7n t\u1eadp V\u0103nM\u1ea1ch","Ng\u1eef li\u1ec7u ngo\xe0i SGK theo \u0111\u1ecbnh h\u01b0\u1edbng GDPT 2018 (L\u1edbp 10)","Trong th\u1ebf gi\u1edbi ng\u1eadp tr\xe0n th\xf4ng tin, ai c\u0169ng c\xf3 th\u1ec3 l\xean ti\u1ebfng ch\u1ec9 sau m\u1ed9t c\xfa ch\u1ea1m m\xe0n h\xecnh, nh\u01b0ng kh\xf4ng ph\u1ea3i ai c\u0169ng \u0111\u1ee7 ki\xean nh\u1eabn \u0111\u1ec3 l\u1eafng nghe \u0111\u1ebfn t\u1eadn c\xf9ng. L\u1eafng nghe th\u1ef1c s\u1ef1 kh\xf4ng ch\u1ec9 l\xe0 gi\u1eef im l\u1eb7ng ch\u1edd \u0111\u1ebfn l\u01b0\u1ee3t m\xecnh n\xf3i. \u0110\xf3 l\xe0 kh\u1ea3 n\u0103ng t\u1ea1m g\xe1c \u0111\u1ecbnh ki\u1ebfn \u0111\u1ec3 \u0111\u1eb7t m\xecnh v\xe0o c\xe2u chuy\u1ec7n, nh\u1ecbp c\u1ea3m x\xfac v\xe0 ho\xe0n c\u1ea3nh c\u1ee7a ng\u01b0\u1eddi \u0111\u1ed1i di\u1ec7n. M\u1ed9t l\u1eddi khuy\xean v\u1ed9i v\xe0ng \u0111\xf4i khi k\xe9m gi\xe1 tr\u1ecb h\u01a1n r\u1ea5t nhi\u1ec1u so v\u1edbi s\u1ef1 hi\u1ec7n di\u1ec7n ch\u0103m ch\xfa v\xe0 m\u1ed9t c\xe2u h\u1ecfi g\u1ee3i m\u1edf ch\xe2n th\xe0nh. Khi bi\u1ebft l\u1eafng nghe, ng\u01b0\u1eddi tr\u1ebb kh\xf4ng ch\u1ec9 m\u1edf r\u1ed9ng hi\u1ec3u bi\u1ebft t\u1eeb g\xf3c nh\xecn \u0111a chi\u1ec1u m\xe0 c\xf2n l\xe0m d\u1ecbu b\u1edbt nh\u1eefng hi\u1ec3u l\u1ea7m kh\xf4ng \u0111\xe1ng c\xf3 trong gia \u0111\xecnh, l\u1edbp h\u1ecdc v\xe0 c\u1ed9ng \u0111\u1ed3ng m\u1ea1ng. H\u1ecdc c\xe1ch nghe ch\u1eadm l\u1ea1i c\u0169ng ch\xednh l\xe0 c\xe1ch r\xe8n luy\u1ec7n t\u01b0 duy ph\u1ea3n bi\u1ec7n t\u1ec9nh t\xe1o tr\u01b0\u1edbc m\u1ecdi lu\u1ed3ng d\u01b0 lu\u1eadn \u1ed3n \xe0o.",B.a28],t.yf)
